const int MOD = 1000000007;

class Solution {
public:
    long long quickPow(long long a, long long e) {
        long long result = 1;
        while (e > 0) {
            if (e & 1) result = result * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return result;
    }

    int numberOfSets(int n, int k) {
        int m = 2 * k;
        long long numerator = 1, denominator = 1;
        for (int i = 1; i <= m; i++) {
            numerator = numerator * (n + k - i) % MOD;
            denominator = denominator * i % MOD;
        }
        return numerator * quickPow(denominator, MOD - 2) % MOD;
    }
};

constexpr int N=1e5, INF=1e9;
int lens[N];
class Solution {
public:
    static int minSumOfLengths(vector<int>& arr, int target) {
        const int n=arr.size();
        int prv=INF, ans=INF, sum=0;
        for(int l=0, r=0; r<n; r++){
            sum+=arr[r];
            for(; sum>target; l++)
                sum-=arr[l];
            lens[r]=prv;
            if (sum==target){
                int len=r-l+1;
                if (l>0) 
                    ans=min(ans, len+lens[l-1]);
                lens[r]=min(lens[r], len);
            }
            prv=lens[r];
        }
        return ans>=INF?-1:ans;

    }
};

class Solution {
public:
    vector<string> maxNumOfSubstrings(string s) {
        int count[26] = {};
        int first[26], last[26];

        fill(first, first + 26, -1);
        fill(last, last + 26, -1);

        vector<int> order;

        for (int i = 0; i < s.size(); i++) {
            int c = s[i] - 'a';

            if (count[c] == 0) {
                first[c] = i;
                order.push_back(c);
            }

            count[c]++;
            last[c] = i;
        }

        vector<string> res;
        deque<array<int, 3>> queue;

        for (int c : order) {
            queue.push_front({first[c], last[c], count[c]});

            int left = INT_MAX;
            int right = INT_MIN;
            int total = 0;

            for (auto& item : queue) {
                total += item[2];
                left = min(left, item[0]);
                right = max(right, item[1]);

                if (total == right - left + 1) {
                    break;
                }
            }

            if (total == right - left + 1) {
                res.push_back(s.substr(left, right - left + 1));
                queue.clear();
            }
        }

        return res;
    }
};

